// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 n) public {
        vm.assume(n >= 1 && n <= 5);
        for (uint256 i = 0; i < n; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(i)))));
            vm.deal(player, 10);
            vm.prank(player);
            c.play{value: 10}();
        }
        uint256 pot = c.pot();
        uint256 expectedPot = address(c).balance;
        assertEq(pot, expectedPot);
    }
}
